namespace SW2URDF.Test
{
    /// <summary>
    /// Names and expectations of the minimal TWO_BOXES example model (see TESTING.md).
    /// The model is generated by scripts/make_test_fixtures.py; keep both in sync.
    /// </summary>
    public static class TwoBoxesModel
    {
        public const string Name = "TWO_BOXES";
        public const string PartRed = "BOX_RED";
        public const string PartBlue = "BOX_BLUE";

        /// <summary>Both boxes present; the blue part uses its "Tall" configuration.</summary>
        public const string ConfigBoth = "CFG_BOTH";

        /// <summary>The blue box is suppressed.</summary>
        public const string ConfigRedOnly = "CFG_RED_ONLY";

        public const string BlueShort = "Short";
        public const string BlueTall = "Tall";


        /// <summary>The whole model should stay tiny so it is cheap to keep in the repository.</summary>
        public const long MaxTotalBytes = 2 * 1024 * 1024;
    }
}
